def solve():
    # Vertices: 0..14
    # Edges:
    edges = []
    for j in range(5):
        edges.append((3*j + 0, 3*j + 1))
        edges.append((3*j + 1, 3*j + 2))
        edges.append((3*j + 2, 3*j + 0))
    for j in range(4):
        edges.append((3*j + 0, 3*(j+1) + 0))
        edges.append((3*j + 1, 3*(j+1) + 1))
        edges.append((3*j + 2, 3*(j+1) + 2))

    # Labels: 0..27
    # We need to assign 15 distinct labels from 0..27 to the 15 vertices
    # such that the 27 edge differences are distinct and in 1..27.

    # This is a search problem.
    # Let's use backtracking with pruning.

    labels = [-1] * 15
    used_labels = [False] * 28
    used_diffs = [False] * 28

    def backtrack(v_idx):
        if v_idx == 15:
            return True

        for label in range(28):
            if not used_labels[label]:
                labels[v_idx] = label

                # Check if this label assignment violates any edge constraints
                possible = True
                # Check edges connected to v_idx that are fully assigned
                for u, v in edges:
                    if u == v_idx and labels[v] != -1:
                        diff = abs(labels[u] - labels[v])
                        if diff == 0 or used_diffs[diff]:
                            possible = False
                            break
                    elif v == v_idx and labels[u] != -1:
                        diff = abs(labels[u] - labels[v])
                        if diff == 0 or used_diffs[diff]:
                            possible = False
                            break

                if possible:
                    # Mark label and diffs
                    used_labels[label] = True
                    new_diffs = []
                    for u, v in edges:
                        if (u == v_idx and labels[v] != -1) or (v == v_idx and labels[u] != -1):
                            diff = abs(labels[u] - labels[v])
                            used_diffs[diff] = True
                            new_diffs.append(diff)

                    if backtrack(v_idx + 1):
                        return True

                    # Backtrack
                    for diff in new_diffs:
                        used_diffs[diff] = False
                    used_labels[label] = False
                    labels[v_idx] = -1
        return False

    if backtrack(0):
        return labels
    else:
        return None

