from pysat.solvers import Glucose3

def solve():
    # Vertices: 0..14
    # Edges:
    edges = []
    for j in range(5):
        edges.append((3*j + 0, 3*j + 1))
        edges.append((3*j + 1, 3*j + 2))
        edges.append((3*j + 2, 3*j + 0))
    for j in range(4):
        edges.append((3*j + 0, 3*(j+1) + 0))
        edges.append((3*j + 1, 3*(j+1) + 1))
        edges.append((3*j + 2, 3*(j+1) + 2))

    # Variables:
    # x_{v, l} = 1 if vertex v has label l
    # v \in {0..14}, l \in {0..27}
    # Total 15 * 28 = 420 variables

    def get_var(v, l):
        return v * 28 + l + 1

    solver = Glucose3()

    # Each vertex has exactly one label
    for v in range(15):
        solver.add_clause([get_var(v, l) for l in range(28)])
        for l1 in range(28):
            for l2 in range(l1 + 1, 28):
                solver.add_clause([-get_var(v, l1), -get_var(v, l2)])

    # Each label is used at most once
    for l in range(28):
        for v1 in range(15):
            for v2 in range(v1 + 1, 15):
                solver.add_clause([-get_var(v1, l), -get_var(v2, l)])

    # Edge differences must be distinct
    # Let d_{e, k} = 1 if edge e has difference k, k \in {1..27}
    # This is still a lot of variables.
    # Let's use a simpler approach:
    # For each edge e=(u, v), and each pair of labels (l1, l2),
    # if edge e has labels (l1, l2), then the difference is |l1 - l2|.

    # Actually, let's use the constraint that for each edge e,
    # the difference is some k \in {1..27}, and each k is used at most once.

    # Let y_{e, k} = 1 if edge e has difference k
    # e \in {0..26}, k \in {1..27}
    # This is 27 * 27 = 729 variables.

    def get_diff_var(e, k):
        return 15 * 28 + e * 27 + k

    # Each edge has exactly one difference
    for e in range(27):
        solver.add_clause([get_diff_var(e, k) for k in range(1, 28)])
        for k1 in range(1, 28):
            for k2 in range(k1 + 1, 28):
                solver.add_clause([-get_diff_var(e, k1), -get_diff_var(e, k2)])

    # Each difference is used at most once
    for k in range(1, 28):
        for e1 in range(27):
            for e2 in range(e1 + 1, 27):
                solver.add_clause([-get_diff_var(e1, k), -get_diff_var(e2, k)])

    # Link vertex labels to edge differences
    # If vertex u has label l1 and vertex v has label l2,
    # then edge (u, v) must have difference |l1 - l2|
    for e_idx, (u, v) in enumerate(edges):
        for l1 in range(28):
            for l2 in range(28):
                if l1 == l2: continue
                diff = abs(l1 - l2)
                # If u has l1 and v has l2, then edge e_idx must have diff
                # Clause: -(u has l1) or -(v has l2) or (edge e_idx has diff)
                solver.add_clause([-get_var(u, l1), -get_var(v, l2), get_diff_var(e_idx, diff)])

    if solver.solve():
        model = solver.get_model()
        labels = [0] * 15
        for v in range(15):
            for l in range(28):
                if model[get_var(v, l) - 1] > 0:
                    labels[v] = l
                    break
        return labels
    else:
        return None

print(solve())
